do $$
declare w uuid=gen_random_uuid();u uuid=gen_random_uuid();p shop_products;data jsonb;op uuid=gen_random_uuid();sale_key uuid=gen_random_uuid();rid uuid=gen_random_uuid();failed boolean;lines jsonb;rev bigint;other_product shop_products;create_key uuid=gen_random_uuid();begin
 insert into auth.users(id,email) values(u,u||'@example.invalid');
 insert into workspaces(id,salon_name,slug,owner_email,subscription_status,subscription_ends_at) values(w,'Shop fixture','shop-'||w,u||'@example.invalid','active',now()+interval '1 year');
 insert into workspace_members(workspace_id,user_id,email) values(w,u,u||'@example.invalid');
 perform set_config('request.jwt.claim.sub',u::text,true);
 data=jsonb_build_object('name','Shampoo','sku','TEST','purpose','both','unit','ml','pack_size',250,'price_cents',2000,'cost_cents',800,'minimum_retail',2,'minimum_professional',50);
 failed=false;begin perform shop_save_product(null,0,data);exception when others then failed=true;end;
 if not failed then raise exception 'Disabled shop accepted product';end if;
 perform shop_set_enabled(true,1);p=shop_create_product(create_key,data);other_product=shop_create_product(create_key,data);
 if p.id<>other_product.id then raise exception 'Duplicate product on retry';end if;
 failed=false;begin perform shop_save_product(p.id,null,data);exception when others then failed=true;end;
 if not failed then raise exception 'Missing revision bypasses product conflict';end if;
 perform shop_adjust_stock(op,p.id,'retail','receive',5,'Carico iniziale',p.stock_revision);
 perform shop_adjust_stock(op,p.id,'retail','receive',5,'Carico iniziale',p.stock_revision);
 if (select retail_qty from shop_products where id=p.id)<>5 then raise exception 'Duplicate stock movement';end if;
 failed=false;begin perform shop_adjust_stock(op,p.id,'retail','receive',6,'Carico iniziale',p.stock_revision);exception when others then failed=true;end;
 if not failed then raise exception 'Different payload accepted';end if;
 failed=false;begin perform shop_adjust_stock(gen_random_uuid(),p.id,'retail','count',10,'Conteggio',p.stock_revision);exception when others then failed=true;end;
 if not failed then raise exception 'Stale inventory count overwrote movements';end if;
 perform shop_adjust_stock(gen_random_uuid(),p.id,'retail','transfer',1,'Uso salone',0);
 if (select professional_qty from shop_products where id=p.id)<>250 or (select retail_qty from shop_products where id=p.id)<>4 then raise exception 'Wrong unit conversion';end if;
 perform shop_adjust_stock(gen_random_uuid(),p.id,'professional','consume',30.5,'Trattamento',0);
 if (select professional_qty from shop_products where id=p.id)<>219.5 then raise exception 'Wrong professional consumption';end if;
 lines=jsonb_build_array(jsonb_build_object('id',p.id,'quantity',2,'revision',p.revision));
 perform shop_checkout(sale_key,null,'cash',lines);perform shop_checkout(sale_key,null,'cash',lines);
 if (select retail_qty from shop_products where id=p.id)<>2 or (select count(*) from shop_sales where workspace_id=w)<>1 then raise exception 'Checkout deducted twice';end if;
 if (select amount from cash_movements where id=(select cash_movement_id from shop_sales where id=sale_key))<>40 then raise exception 'Cash not linked';end if;
 failed=false;begin perform shop_checkout(gen_random_uuid(),null,'cash',jsonb_build_array(jsonb_build_object('id',p.id,'quantity',3,'revision',p.revision)));exception when others then failed=true;end;
 if not failed then raise exception 'Oversell accepted';end if;
 failed=false;begin update cash_movements set amount=1 where id=(select cash_movement_id from shop_sales where id=sale_key);exception when others then failed=true;end;
 if not failed then raise exception 'Cash sale overwritten';end if;
 p=shop_save_product(p.id,p.revision,data||'{"price_cents":2500}');
 failed=false;begin perform shop_checkout(gen_random_uuid(),null,'cash',lines);exception when others then failed=true;end;
 if not failed then raise exception 'Stale price accepted';end if;
 if (select unit_price_cents from shop_sale_lines where sale_id=sale_key and product_id=p.id limit 1)<>2000 then raise exception 'Snapshot changed';end if;
 perform shop_return(rid,sale_key,p.id,1,true,'Reso integro');perform shop_return(rid,sale_key,p.id,1,true,'Reso integro');
 if (select retail_qty from shop_products where id=p.id)<>3 then raise exception 'Return duplicated';end if;
 if (select amount from cash_movements where id=(select cash_movement_id from shop_sales where id=sale_key))<>40 or (select amount from cash_movements where shop_return_id=rid)<>-20 then raise exception 'Refund changed original sale or wrong outflow';end if;
 failed=false;begin update cash_movements set amount=0 where shop_return_id=rid;exception when others then failed=true;end;
 if not failed then raise exception 'Refund rewritten';end if;
 failed=false;begin perform shop_adjust_stock(gen_random_uuid(),p.id,'retail','count',50,'Count missing revision',null);exception when others then failed=true;end;
 if not failed then raise exception 'Missing stock revision overwrites movements';end if;
 failed=false;begin perform shop_checkout(gen_random_uuid(),null,'cash',null);exception when others then failed=true;end;
 if not failed then raise exception 'Empty checkout accepted';end if;
 failed=false;begin perform shop_import_products(gen_random_uuid(),jsonb_build_array(data||'{"sku":"OTHER"}',data));exception when others then failed=true;end;
 if not failed or exists(select 1 from shop_products where workspace_id=w and sku='OTHER') then raise exception 'Import partially committed';end if;
 perform shop_set_enabled(false,2);
 perform shop_return(gen_random_uuid(),sale_key,p.id,1,false,'Prodotto danneggiato');
 if (select retail_qty from shop_products where id=p.id)<>3 then raise exception 'Damaged stock resold';end if;
 failed=false;begin perform shop_return(gen_random_uuid(),sale_key,p.id,1,true,'Reso eccessivo');exception when others then failed=true;end;
 if not failed then raise exception 'Excess return accepted';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 failed=false;begin perform shop_console();exception when others then failed=true;end;
 if not failed then raise exception 'Foreign identity reads shop';end if;
 failed=false;begin perform shop_return(gen_random_uuid(),sale_key,p.id,1,true,'Foreign attempt');exception when others then failed=true;end;
 if not failed then raise exception 'Foreign identity changes stock';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 if has_table_privilege('authenticated','shop_products','UPDATE') or has_function_privilege('anon','shop_checkout(uuid,uuid,payment_method,jsonb)','EXECUTE') then raise exception 'Excess privileges';end if;
 select revision into rev from shop_sync_revisions where workspace_id=w;if rev<5 then raise exception 'Missing realtime invalidations';end if;
end $$;
